            var prior=BeforeState(w,q.At,q.Revision-1);prior.CommitSequence=q.Revision;var pickup=q.Input.Action==NewMilitaryAction.Pickup?NoticeId(prior,MilitaryEffect.PickedUp,q.Input.Id.Value):"";RemoveGenerated(prior,new[]{q.Message??"",pickup});Dispatch(prior,q.Input);
