        long carry=0,depot=MilitaryEconomy.InitialStock(w);var ledger=s.Moves.Select(m=>(At:m.At,Rank:1,Revision:s.Requests.Single(q=>q.Input.Id==m.Id).Revision,Move:(SupplyMove?)m,Use:(SupplyUse?)null,Credit:0L)).Concat(s.Uses.Select(u=>(At:u.Until,Rank:0,Revision:0L,Move:(SupplyMove?)null,Use:(SupplyUse?)u,Credit:0L))).Concat(MilitaryEconomy.Transfers(w,w.ElapsedSeconds,w.CommitSequence+1).Where(e=>e.Input.Depot==DepotFor(w)).Select(e=>(At:e.At,Rank:1,Revision:e.Revision,Move:(SupplyMove?)null,Use:(SupplyUse?)null,Credit:checked((e.Input.Returning?-e.Input.RiceKg:e.Input.RiceKg)*MilitaryEconomy.PersonSecondsPerKg)))).Concat(FieldConvoy.Credits(w,CarryFor(w),w.ElapsedSeconds,w.CommitSequence+1).Select(e=>(At:e.At,Rank:2,Revision:e.Revision,Move:(SupplyMove?)null,Use:(SupplyUse?)null,Credit:e.Amount))).OrderBy(x=>x.At).ThenBy(x=>x.Rank).ThenBy(x=>x.Revision);
        foreach(var e in ledger){if(e.Move is {} m){long delta=m.Loading?m.Amount:-m.Amount;carry=checked(carry+delta);depot=checked(depot-delta);Need(carry>=0&&carry<=Capacity&&depot>=0,"兵糧が過剰引当されています");}else if(e.Use is {} u){Need(u.Consumed==Math.Min(carry,checked(u.Soldiers*(u.Until-u.From))),"兵糧消費と在庫が違います");carry-=u.Consumed;}else if(e.Rank==2){carry=checked(carry+e.Credit);Need(carry<=Capacity,"集合地の受入容量を超えています");}else{depot=checked(depot+e.Credit);Need(depot>=0,"軍用倉の米を過剰返納しています");}}
